"use strict";
module.exports = /*#__PURE__*/JSON.parse('{"title":"CT重建和螺旋CT","description":"本页面介绍CT重建技术和螺旋CT的原理，包括反投影、滤波反投影和螺距的概念。","sections":[{"id":"backprojection","title":"反投影","description":"反投影是CT重建的基本方法，通过将投影数据\\"涂抹\\"回图像空间来重建图像。","content":"为了理解CT重建，我们首先需要理解计算机断层扫描仪的工作原理。简单来说，它通过在不同角度拍摄X射线投影来获取人体内部结构的信息。在任何给定角度，投影是一条由明暗像素组成的线，取决于X射线如何被组织衰减。有时人们谈论正弦图，它只是将所有不同角度的投影堆叠在一起形成的显示。","simulator":{"type":"backprojection","options":{"images":[{"id":"abdomen","name":"腹部","src":"/images/abdomen.png"},{"id":"phantom","name":"模型","src":"/images/phantom.png"}],"fanBeamAngles":[{"value":30,"name":"30度"},{"value":60,"name":"60度"},{"value":90,"name":"90度"}]}},"keyPoints":["反投影是将投影数据\\"涂抹\\"回图像空间的过程","标准反投影会产生模糊的图像","需要180度的数据才能重建图像","扇形束几何中，物体的一部分必须包含在所有180度的投影中才能正确重建"]},{"id":"filtered-backprojection","title":"滤波反投影","description":"滤波反投影通过在反投影前对投影数据应用滤波器来改善图像质量。","content":"正如您可能已经注意到的，反投影会使最终图像变模糊。为了解决由标准反投影创建的模糊问题，我们使用滤波反投影。滤波是指在进行反投影之前改变投影数据。所需的滤波器类型是高通滤波器，或锐化滤波器。这种类型的滤波器会增强投影中的锐边缘，并倾向于忽略平坦区域。因为高通滤波器实际上会在边缘处创建负像素，它会减去由反投影引起的额外模糊。","keyPoints":["滤波反投影使用高通滤波器来增强边缘","高通滤波器在边缘处创建负像素，减少模糊","滤波反投影是现代CT扫描仪中使用的标准重建方法"]},{"id":"helical-ct","title":"螺旋CT和螺距","description":"螺旋CT技术使用连续旋转的X射线源和探测器，同时患者床持续移动，形成螺旋扫描路径。","content":"早期的CT扫描仪一次只扫描人体的一个切片，然后再移动到下一个切片。因此，切片的厚度仅取决于CT探测器的宽度。由于扫描仪对准光束到探测器的宽度，切片厚度也可以说等于准直器宽度。\\n\\n现代CT技术使用所谓的螺旋（或\\"螺旋\\"）路径。在螺旋CT中，扫描仪不断旋转，患者床也不断移动。因此，在同一切片（z位置）获取两个CT投影的情况下构成了螺旋路径。\\n\\n螺距是指床移动距离与准直器宽度的比值。螺距为1.0时，相邻螺旋之间刚好无间隙；螺距小于1.0时，相邻螺旋之间有重叠，图像质量更高但辐射剂量更大；螺距大于1.0时，相邻螺旋之间有间隙，扫描速度更快但可能丢失信息。\\n\\n现代螺旋CT从两个相隔180度的投影中平均（或\\"插值\\"）数据。光子无论是从组织\\"向前\\"还是\\"向后\\"通过，都会经历相同的衰减——因此相隔180度的角度是等效的。这种插值是为了将螺旋路径转换为横断面切片。这也解释了切片加宽的概念——每个点反映了来自两个z位置的数据，这些位置由床移动的速度决定，因为光束旋转180度。","simulator":{"type":"helical-ct","options":{"images":[{"id":"body","name":"人体模型","src":"/images/body.png"},{"id":"ctsim_a30","name":"CT模拟30°","src":"/images/ctsim_a30.gif"},{"id":"ctsim_a60","name":"CT模拟60°","src":"/images/ctsim_a60.gif"},{"id":"ctsim_a90","name":"CT模拟90°","src":"/images/ctsim_a90.gif"},{"id":"helical_30","name":"螺旋CT 30°","src":"/images/helical_30.gif"},{"id":"helical_60","name":"螺旋CT 60°","src":"/images/helical_60.gif"},{"id":"helical_90","name":"螺旋CT 90°","src":"/images/helical_90.gif"}],"pitchValues":[{"value":0.5,"name":"0.5 (重叠扫描)","description":"相邻螺旋之间有50%的重叠，图像质量高但辐射剂量大"},{"value":1,"name":"1.0 (无间隙扫描)","description":"相邻螺旋之间刚好无间隙，平衡了图像质量和辐射剂量"},{"value":1.5,"name":"1.5 (小间隙扫描)","description":"相邻螺旋之间有小间隙，扫描速度较快，可能有轻微信息丢失"},{"value":2,"name":"2.0 (大间隙扫描)","description":"相邻螺旋之间有大间隙，扫描速度快但可能丢失信息"}]}},"keyPoints":["螺旋CT技术使X射线源和探测器连续旋转，同时患者床持续移动","螺距是床移动距离与准直器宽度的比值，影响图像质量和扫描速度","螺距小于1.0时有重叠扫描，图像质量更高但辐射剂量更大","螺距大于1.0时有间隙扫描，扫描速度更快但可能丢失信息","现代螺旋CT通过插值技术将螺旋路径数据转换为横断面切片"]}]}');

